import type { ControlUiSkin } from "@/components/control-ui/skin";

export const skin: ControlUiSkin = {
  id: "linear",
  // Linear's rail is narrower than shadcn's 16rem default and never draws surface of its own.
  sidebarWidth: "15.25rem",
};

/* Only what Tailwind classes cannot say — everything else lives in skin.config or theme.css. */

[data-skin="linear"] {
  /* Linear draws its edges at half a device pixel; below 2dppx that would vanish, so it thickens. */
  --linear-hairline: 1px;

  /* Row fills derive from --foreground, so one declaration serves every surface the row can land on.
     Light darkens less than dark lightens — measured off the app, not mirrored. */
  --linear-row-hover: oklch(from var(--foreground) l c h / 0.035);
  --linear-row-active: oklch(from var(--foreground) l c h / 0.06);
  --linear-control-bg: var(--popover);
  --linear-control-hover: oklch(from var(--foreground) l c h / 0.06);
  --linear-control-active: oklch(from var(--foreground) l c h / 0.09);

  /* The brand ramp: Linear darkens the indigo on press rather than fading it. */
  --linear-primary-hover: oklch(0.5897 0.1527 276.397); /* #6771d6 */
  --linear-primary-active: oklch(0.5177 0.1507 275.398); /* #525cbd */

  /* Own vars rather than the shared shadow tokens, so each surface tier stays tunable on its own.
     Each stack is Linear's own recipe: many near-transparent layers, never one big blur. */
  --linear-control-shadow: 0 3px 6px -2px oklch(0 0 0 / 0.02), 0 1px 1px 0 oklch(0 0 0 / 0.04);
  --linear-panel-shadow: 0 3px 6px -2px oklch(0 0 0 / 0.02), 0 1px 1px 0 oklch(0 0 0 / 0.04);
  --linear-menu-shadow: 0 6px 18px 0 oklch(0 0 0 / 0.02), 0 3px 9px 0 oklch(0 0 0 / 0.04), 0 1px 1px 0 oklch(0 0 0 / 0.04);
  --linear-modal-shadow:
    0 4px 40px 0 oklch(0 0 0 / 0.1), 0 3px 20px 0 oklch(0 0 0 / 0.12), 0 3px 12px 0 oklch(0 0 0 / 0.12), 0 2px 8px 0 oklch(0 0 0 / 0.12),
    0 1px 1px 0 oklch(0 0 0 / 0.12);

  /* Menus carry their own edge: on ink it reads lighter than --border, on paper barely darker. */
  --linear-menu-border: oklch(0.931 0 0); /* #e8e8e8 */

  --linear-tab-active-bg: var(--popover);
  --linear-tab-active-shadow: 0 0 0 var(--linear-hairline) var(--border), 0 1px 1px 0 oklch(0 0 0 / 0.04);
}

@media (min-resolution: 2dppx) {
  [data-skin="linear"] {
    --linear-hairline: 0.5px;
  }
}

/* Dark: raised surfaces get lighter, not brighter-edged; shadows go deep and neutral. */
:where(.dark) [data-skin="linear"],
.dark[data-skin="linear"] {
  --linear-row-hover: oklch(1 0 0 / 0.06);
  --linear-row-active: oklch(1 0 0 / 0.105);
  --linear-control-bg: oklch(1 0 0 / 0.05);
  --linear-control-hover: oklch(1 0 0 / 0.08);
  --linear-control-active: oklch(1 0 0 / 0.12);
  --linear-control-shadow: 0 0.5px 1px 1px oklch(0 0 0 / 0.3);
  --linear-panel-shadow: 0 0.5px 1px 1px oklch(0 0 0 / 0.3);
  --linear-menu-shadow: 0 3px 8px 0 oklch(0 0 0 / 0.125), 0 2px 5px 0 oklch(0 0 0 / 0.125), 0 1px 1px 0 oklch(0 0 0 / 0.125);
  --linear-modal-shadow:
    0 4px 40px 0 oklch(0 0 0 / 0.4), 0 3px 20px 0 oklch(0 0 0 / 0.5), 0 3px 12px 0 oklch(0 0 0 / 0.5), 0 2px 8px 0 oklch(0 0 0 / 0.5),
    0 1px 1px 0 oklch(0 0 0 / 0.5);
  --linear-menu-border: oklch(0.3602 0.0053 271.268); /* #3c3d40 */
  --linear-tab-active-bg: oklch(1 0 0 / 0.07);
  --linear-tab-active-shadow: none;
}

@layer base {
  /* Body-level, not a utility: type rendering is inherited, so portalled popups pick it up too. */
  :root[data-skin="linear"] body {
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }
}

@layer components {
  [data-skin="linear"]
    :where(
      [data-control-ui="button"][data-slot="root"][data-control-family="button"],
      [data-control-ui="toggle"][data-slot="root"][data-control-family="button"]
    ) {
    --cui-button-gap: 0.375rem;
    --cui-button-radius: var(--radius-control);
    --cui-button-press-scale: 1;
    --cui-button-hover-bg: var(--linear-row-hover);
    --cui-button-active-bg: var(--linear-row-active);
    --cui-button-active-hover-bg: var(--linear-row-active);
    transition-property: color, background-color, border-color, box-shadow;
  }

  [data-skin="linear"]
    :where(
      [data-control-ui="button"][data-slot="root"][data-variant="solid"][data-control-family="button"],
      [data-control-ui="toggle"][data-slot="root"][data-variant="solid"][data-control-family="button"]
    ) {
    --cui-button-hover-bg: var(--linear-primary-hover);
    --cui-button-press-bg: var(--linear-primary-active);
    --cui-button-shadow: var(--linear-control-shadow);
  }

  [data-skin="linear"]
    :where(
      [data-control-ui="button"][data-slot="root"][data-variant="surface"][data-control-family="button"],
      [data-control-ui="toggle"][data-slot="root"][data-variant="surface"][data-control-family="button"]
    ) {
    --cui-button-bg: var(--linear-control-bg);
    --cui-button-hover-bg: var(--linear-control-hover);
    --cui-button-press-bg: var(--linear-control-active);
    --cui-button-shadow: inset 0 0 0 var(--linear-hairline) var(--border), var(--linear-control-shadow);
    --cui-button-active-shadow: inset 0 0 0 var(--linear-hairline) oklch(from var(--primary) l c h / 0.6), var(--linear-control-shadow);
  }

  [data-skin="linear"]
    :where(
      [data-control-ui="button"][data-slot="root"][data-tone="danger"][data-variant="solid"][data-control-family="button"],
      [data-control-ui="toggle"][data-slot="root"][data-tone="danger"][data-variant="solid"][data-control-family="button"]
    ) {
    --cui-button-hover-bg: var(--destructive);
    --cui-button-press-bg: var(--destructive);
    --cui-button-shadow: var(--linear-control-shadow);
  }

  @media (hover: hover) {
    [data-skin="linear"]
      :where(
        [data-control-ui="button"][data-tone="danger"][data-variant="solid"][data-control-family="button"]:hover,
        [data-control-ui="toggle"][data-tone="danger"][data-variant="solid"][data-control-family="button"]:hover
      ) {
      filter: brightness(1.05);
    }
  }

  [data-skin="linear"]
    :where(
      [data-control-ui="button"][data-tone="danger"][data-variant="solid"][data-control-family="button"]:active,
      [data-control-ui="toggle"][data-tone="danger"][data-variant="solid"][data-control-family="button"]:active
    ) {
    filter: brightness(0.95);
  }

  [data-skin="linear"]
    :where(
      [data-slot="root"][data-variant="inverse"][data-control-family="toolbar"]
        [data-control-ui="button"][data-slot="root"][data-control-family="button"]
    ) {
    --cui-button-bg: transparent;
    --cui-button-foreground: oklch(from var(--background) l c h / 0.7);
    --cui-button-hover-bg: oklch(from var(--background) l c h / 0.1);
    --cui-button-hover-foreground: var(--background);
    --cui-button-press-bg: oklch(from var(--background) l c h / 0.12);
    --cui-button-active-bg: var(--background);
    --cui-button-active-foreground: var(--foreground);
    --cui-button-active-hover-bg: var(--background);
    --cui-button-shadow: 0 0 transparent;
    --cui-button-active-shadow: 0 0 transparent;
  }

  /* Re-values the library's pill knobs: a flat ink wash, never a raised card. */
  [data-skin="linear"] :where([data-slot="root"][data-control-family="track-highlight"]) {
    --cui-track-highlight-background: var(--linear-row-active);
    --cui-track-highlight-ring-color: transparent;
    --cui-track-highlight-shadow: none;
  }

  /* Re-values the component-local knobs only, so geometry, states, and the `line` variant stay baseline. */
  [data-skin="linear"] :where([data-slot="root"][data-control-family="tabs"]) {
    --cui-tabs-trigger-radius: var(--radius-control);
    --cui-tabs-list-padding: 0rem;
    --cui-tabs-list-background: transparent;
    --cui-tabs-border-color: var(--border);
    --cui-tabs-indicator-background: var(--linear-tab-active-bg);
    --cui-tabs-indicator-shadow: var(--linear-tab-active-shadow);
  }
}

@layer components {
  [data-skin="linear"]
    :where(
      [data-control-family="popup"][data-popup-part="surface"]:not([data-popup-kind="tooltip"]),
      [data-control-family="popup"][data-popup-part="list-surface"]
    ) {
    --cui-popup-background: var(--popover);
    --cui-popup-border-color: var(--linear-menu-border);
    --cui-popup-border-width: var(--linear-hairline);
    --cui-popup-shadow: var(--linear-menu-shadow);
  }

  /* 6px block padding on a 20px line lands the row on Linear's 32px, without touching --control-h-xs. */
  [data-skin="linear"] :where([data-popup-part="item"]) {
    padding: 0.375rem 0.5rem;
    font-size: var(--text-label);
  }

  [data-skin="linear"] :where([data-popup-part="label"]) {
    padding: 0.25rem 0.5rem;
    font-size: var(--text-caption);
    letter-spacing: normal;
    text-transform: none;
  }

  [data-skin="linear"]
    :where(
      [data-control-family="popup"][data-popup-part="surface"],
      [data-control-family="popup"][data-popup-part="list-surface"],
      [data-control-family="popup"][data-popup-part="bar"]
    ) {
    --cui-popup-item-radius: var(--radius-popup-item);
    --cui-popup-item-highlight-background: var(--linear-row-hover);
    --cui-popup-item-disabled-opacity: 0.4;
    --cui-popup-separator-color: var(--border);
  }

  [data-skin="linear"] :where([data-popup-part="separator"]) {
    margin-inline: 0;
  }

  [data-skin="linear"] :where([data-popup-part="shortcut"]) {
    margin-inline-start: auto;
    font-size: var(--text-caption);
    letter-spacing: normal;
  }

  [data-skin="linear"] :where([data-control-ui="select"][data-slot="trigger"][data-control-family="button"]) {
    --cui-button-bg: transparent;
    --cui-button-hover-bg: var(--linear-row-hover);
    --cui-button-shadow: inset 0 0 0 var(--linear-hairline) var(--input);
    --cui-button-press-scale: 1;
  }

  [data-skin="linear"]
    :where(
      [data-control-ui="dropdown-menu"][data-slot="trigger"][data-control-family="button"],
      [data-control-ui="menubar"][data-slot="trigger"][data-control-family="button"]
    ) {
    --cui-button-bg: transparent;
    --cui-button-hover-bg: var(--linear-row-hover);
    --cui-button-shadow: none;
    --cui-button-press-scale: 1;
  }
  [data-skin="linear"]
    :where(
      [data-control-ui="dialog"][data-popup-part="surface"][data-control-family="popup"],
      [data-control-ui="alert-dialog"][data-popup-part="surface"][data-control-family="popup"]
    ) {
    --cui-popup-radius: var(--radius-panel);
    --cui-popup-background: var(--popover);
    --cui-popup-border-color: transparent;
    --cui-popup-border-width: var(--linear-hairline);
    --cui-popup-shadow: var(--linear-modal-shadow);
  }

  .dark[data-skin="linear"]
    :where(
      [data-control-ui="dialog"][data-popup-part="surface"][data-control-family="popup"],
      [data-control-ui="alert-dialog"][data-popup-part="surface"][data-control-family="popup"]
    ),
  :where(.dark)
    [data-skin="linear"]
    :where(
      [data-control-ui="dialog"][data-popup-part="surface"][data-control-family="popup"],
      [data-control-ui="alert-dialog"][data-popup-part="surface"][data-control-family="popup"]
    ) {
    --cui-popup-border-color: var(--border);
  }

  [data-skin="linear"]
    :where(
      [data-control-ui="dialog"][data-slot="title"][data-control-family="popup"],
      [data-control-ui="alert-dialog"][data-slot="title"][data-control-family="popup"]
    ) {
    font-size: var(--text-body-lg);
    font-weight: 600;
    letter-spacing: -0.01em;
  }

  [data-skin="linear"] :where([data-control-ui="sheet"][data-popup-part="surface"][data-control-family="popup"]) {
    --cui-popup-background: var(--popover);
    --cui-popup-border-color: var(--border);
    --cui-popup-border-width: var(--linear-hairline);
    --cui-popup-shadow: var(--linear-modal-shadow);
  }
}

@layer components {
  [data-skin="linear"] :where([data-control-family="field"][data-control="true"]) {
    --cui-field-radius: var(--radius-control);
    --cui-field-background: transparent;
    --cui-field-foreground: var(--foreground);
    --cui-field-border-color: var(--input);
    --cui-field-border-width: var(--linear-hairline);
    --cui-field-shadow: 0 0 transparent;
    --cui-field-focus-border-color: var(--primary);
  }

  [data-skin="linear"] :where([data-control-ui="combobox"][data-slot="trigger"][data-control-family="field"]) {
    border-radius: var(--radius-control);
    background: transparent;
    box-shadow: none;
  }

  @media (hover: hover) {
    [data-skin="linear"] :where([data-control-ui="combobox"][data-slot="trigger"][data-control-family="field"]):hover {
      background: var(--linear-row-hover);
    }
  }
}

@layer components {
  [data-skin="linear"] :where([data-slot="root"][data-control-family="card"]) {
    --cui-card-radius: var(--radius-panel);
    --cui-card-background: var(--card);
    --cui-card-shadow: none;
  }
}
@layer components {
  [data-skin="linear"] :where([data-control-ui="checkbox"][data-choice-kind="checkbox"][data-slot="root"][data-control-family="choice"]) {
    --cui-choice-radius: max(3px, calc(var(--radius-control) * 0.5));
    --cui-choice-border-color: var(--input);
  }

  [data-skin="linear"]
    :where([data-control-ui="radio-group"][data-choice-kind="radio-group"][data-slot="item"][data-control-family="choice"]) {
    --cui-choice-border-color: var(--input);
  }

  [data-skin="linear"] :where([data-control-ui="slider"][data-slot="root"][data-control-family="range"]) {
    --cui-range-indicator-background: var(--primary);
    --cui-range-thumb-radius: 9999px;
    --cui-range-thumb-background: var(--card);
    --cui-range-thumb-border-color: var(--border);
    --cui-range-thumb-shadow: var(--linear-control-shadow);
  }

  [data-skin="linear"]
    :where(
      [data-control-ui="progress"][data-slot="root"][data-control-family="range"],
      [data-control-ui="meter"][data-slot="root"][data-control-family="range"]
    ) {
    --cui-range-indicator-background: var(--primary);
  }

  [data-skin="linear"] :where([data-slot="root"][data-control-family="thread-rail"]) {
    --cui-thread-rail-popover-background: var(--popover);
    --cui-thread-rail-popover-border-color: var(--linear-menu-border);
    --cui-thread-rail-popover-border-width: var(--linear-hairline);
    --cui-thread-rail-popover-shadow: var(--linear-menu-shadow);
    --cui-thread-rail-item-radius: 9999px;
    --cui-thread-rail-item-background: var(--linear-row-active);
  }

  [data-skin="linear"] :where([data-control-ui="command"][data-slot="root"][data-control-family="popup"]) {
    --cui-popup-background: var(--popover);
    --cui-popup-border-color: var(--linear-menu-border);
    --cui-popup-border-width: var(--linear-hairline);
    --cui-popup-shadow: var(--linear-menu-shadow);
    overflow: hidden;
  }

  [data-skin="linear"] :where([data-control-ui="command"][data-popup-part="bar"][data-control-family="popup"]) {
    --cui-popup-separator-color: var(--border);
    --cui-popup-item-radius: var(--radius-popup-item);
    --cui-popup-item-highlight-background: var(--linear-row-hover);
    --cui-popup-item-disabled-opacity: 0.4;
    --cui-popup-shortcut-foreground: var(--muted-foreground);
  }

  [data-skin="linear"] :where([data-slot="menu-button"][data-control-family="sidebar"]) {
    font-weight: var(--font-weight-medium);
  }

  [data-skin="linear"] :where([data-slot="root"][data-control-family="sidebar"]) {
    --cui-sidebar-inner-background: transparent;
    --cui-sidebar-inner-border-width: 0px;
    --cui-sidebar-menu-button-radius: var(--radius-control);
    --cui-sidebar-menu-button-foreground: var(--muted-foreground);
    --cui-sidebar-menu-button-hover-background: var(--linear-row-hover);
    --cui-sidebar-menu-button-hover-foreground: var(--foreground);
    --cui-sidebar-menu-button-active-background: var(--linear-row-active);
    --cui-sidebar-menu-button-active-foreground: var(--foreground);
    --cui-sidebar-group-label-foreground: var(--muted-foreground);
  }

  [data-skin="linear"] :where([data-slot="group-label"][data-control-family="sidebar"]) {
    padding-inline: calc(var(--spacing) * 2);
    font-size: var(--text-caption);
    font-weight: var(--font-weight-medium);
  }

  [data-skin="linear"] :where([data-slot="content"][data-control-family="sidebar-layout"]) {
    border-radius: var(--radius-panel);
    border-color: var(--border);
    background-color: var(--card);
    box-shadow: var(--linear-panel-shadow);
  }

  [data-skin="linear"] :where([data-slot="root"][data-control-family="tree"]) {
    --cui-tree-item-trigger-radius: var(--radius-control);
    --cui-tree-item-trigger-foreground: var(--muted-foreground);
    --cui-tree-item-trigger-hover-background: var(--linear-row-hover);
    --cui-tree-item-trigger-hover-foreground: var(--foreground);
    --cui-tree-item-trigger-selected-background: var(--linear-row-active);
    --cui-tree-item-trigger-selected-foreground: var(--foreground);
    --cui-tree-item-trigger-font-size: var(--text-label);
    --cui-tree-item-trigger-selected-font-weight: 500;
  }

  [data-skin="linear"] :where([data-slot="root"][data-control-family="alert"]) {
    --cui-alert-radius: var(--radius-panel);
    --cui-alert-background: var(--card);
    --cui-alert-shadow: none;
  }

  [data-skin="linear"] :where([data-slot="root"][data-control-family="item"]) {
    --cui-item-radius: var(--radius-control);
    --cui-item-hover-background: var(--linear-row-hover);
    --cui-item-active-scale: 1;
  }

  [data-skin="linear"] :where([data-slot="root"][data-control-family="empty"]) {
    --cui-empty-radius: var(--radius-panel);
    --cui-empty-background: transparent;
    --cui-empty-border-color: var(--border);
    --cui-empty-border-width: 1px;
    --cui-empty-border-style: dashed;
  }

  [data-skin="linear"] :where([data-slot="root"][data-control-family="badge"]) {
    --cui-badge-radius: 9999px;
  }

  [data-skin="linear"] :where([data-slot="root"][data-control-family="kbd"]) {
    --cui-kbd-radius: calc(var(--radius-control) * 0.67);
    --cui-kbd-background: transparent;
    --cui-kbd-shadow: 0 0 transparent;
  }

  [data-skin="linear"] :where([data-slot="root"][data-control-family="scroll-area"]) {
    --cui-scroll-area-thumb-radius: 9999px;
    --cui-scroll-area-thumb-background: oklch(from var(--foreground) l c h / 0.2);
  }

  [data-skin="linear"] :where([data-control-ui="chat-layout"][data-slot="root"][data-control-family="chat-layout"]) {
    --cui-chat-layout-background: var(--card);
    --cui-chat-layout-shadow: var(--linear-panel-shadow);
  }

  [data-skin="linear"] :where([data-slot="root"][data-control-family="chat-message"]) {
    --cui-chat-message-avatar-radius: 9999px;
    --cui-chat-message-avatar-background: var(--linear-control-bg);
    --cui-chat-message-avatar-border-color: var(--border);
    --cui-chat-message-avatar-border-width: var(--linear-hairline);
  }

  [data-skin="linear"] :where([data-control-ui="chat-composer"][data-slot="root"][data-control-family="chat-composer"]) {
    --cui-chat-composer-shell-background: var(--card);
    --cui-chat-composer-shell-border-color: var(--border);
    --cui-chat-composer-shell-radius: var(--radius-field);
    --cui-chat-composer-shell-shadow: var(--linear-panel-shadow);
    --cui-chat-composer-mention-radius: var(--radius-control);
    --cui-chat-composer-mention-border-color: var(--border);
    --cui-chat-composer-mention-border-width: var(--linear-hairline);
    --cui-chat-composer-mention-background: var(--linear-row-hover);
  }

  [data-skin="linear"] :where([data-slot="root"][data-control-family="markdown-block"]) {
    --cui-markdown-block-background: var(--card);
    --cui-markdown-block-shadow: none;
  }

  [data-skin="linear"] :where([data-slot="header"][data-control-family="markdown-block"]) {
    background-color: transparent;
  }

  [data-skin="linear"] :where([data-slot="root"][data-control-family="code"]) {
    --cui-code-background: var(--card);
    --cui-code-shadow: none;
  }

  [data-skin="linear"] :where([data-slot="header"][data-control-family="code"]) {
    background-color: transparent;
  }

  [data-skin="linear"] :where([data-slot="title"][data-control-family="code"]) {
    font-family: var(--font-mono);
    font-size: var(--text-caption);
  }

  [data-skin="linear"] :where([data-slot="root"][data-control-family="code-diff"]) {
    --cui-code-diff-background: var(--card);
    --cui-code-diff-shadow: none;
  }

  [data-skin="linear"] :where([data-slot="header"][data-control-family="code-diff"]) {
    background-color: transparent;
  }

  [data-skin="linear"] :where([data-slot="root"][data-control-family="inline-attachment"]) {
    --cui-inline-attachment-radius: var(--radius-panel);
    --cui-inline-attachment-background: var(--card);
    --cui-inline-attachment-shadow: 0 0 transparent;
    --cui-inline-attachment-content-radius: var(--radius-control);
  }
}

@layer components {
  [data-skin="linear"] :where([data-slot="root"][data-role="user"][data-control-family="chat-message"]) {
    --cui-chat-message-radius: var(--radius-field);
    --cui-chat-message-corner-radius: var(--radius-field);
    --cui-chat-message-background: var(--primary);
    --cui-chat-message-shadow: none;
    --cui-chat-message-foreground: var(--primary-foreground);
  }

  [data-skin="linear"] :where([data-slot="root"][data-role="assistant"][data-control-family="chat-message"]) {
    --cui-chat-message-radius: var(--radius-field);
    --cui-chat-message-corner-radius: var(--radius-field);
    --cui-chat-message-background: transparent;
  }
}

/* Values measured off the running Linear app (light + dark), converted from its LCH tokens to oklch.
   Hairline borders instead of elevation; floating surfaces are the only things allowed a real shadow. */

[data-skin="linear"][data-skin] {
  /* Inter, self-hosted by the app shell (next/font fills --font-inter); host without it falls to the system stack. */
  --font-sans:
    var(--font-inter, "Inter"), "Inter Variable", "SF Pro Display", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --font-mono: "Berkeley Mono", "SFMono Regular", ui-monospace, SFMono-Regular, Consolas, "Liberation Mono", Menlo, monospace;

  /* Type scale: Linear runs one flat 13px band for ALL chrome (nav rows, controls, body) and reserves
     the larger rungs for content headings. Label == body on purpose. */
  --text-label: 0.8125rem; /* 13px — sm controls, nav rows, tooltips */
  --text-body: 0.8125rem; /* 13px — THE workhorse */
  --text-body-lg: 0.9375rem; /* 15px — the editor rung */

  /* Headings stay tight and semibold; no 700 anywhere (Linear tops out at semibold). */
  --text-heading-4: 0.875rem;
  --text-heading-3: 1rem;
  --text-heading-3--line-height: 1.4;
  --text-heading-2: 1.1875rem;
  --text-heading-2--line-height: 1.3;
  --text-heading-1: 1.5rem; /* 24px — the issue-title rung */
  --text-heading-1--line-height: 1.25;
  --text-heading-1--font-weight: 600;
  --text-heading-1--letter-spacing: -0.014em;
  --text-display: 2rem;
  --text-display--line-height: 1.15;
  --text-display--letter-spacing: -0.022em;

  /* Light: the content sheet is off-white (#f9f9fa), never pure white — pure white is reserved for the
     surfaces that float above it. card == background so the shell's frame reads as one sheet. */
  --background: oklch(0.9824 0.0013 286.376); /* #f9f9fa */
  --foreground: oklch(0.2221 0 0); /* #1b1b1b */
  --card: oklch(0.9824 0.0013 286.376);
  --card-foreground: oklch(0.2221 0 0);
  --popover: oklch(1 0 0); /* #ffffff — menus are the one white surface */
  --popover-foreground: oklch(0.3099 0.0035 286.192); /* #303032 */
  --primary: oklch(0.5674 0.1585 275.206); /* #5e6ad2 — THE Linear indigo */
  --primary-foreground: oklch(1 0 0);
  --muted: oklch(0.9343 0.0013 286.374); /* #e9e9ea */
  --muted-foreground: oklch(0.4755 0.0032 286.278); /* #5c5c5e */
  --secondary: oklch(0.9343 0.0013 286.374);
  --secondary-foreground: oklch(0.306 0.0035 286.188); /* #2f2f31 */
  --accent: oklch(0.91 0.0013 286.373); /* #e1e1e2 — the selected-row fill */
  --accent-foreground: oklch(0.2221 0 0);
  --destructive: oklch(0.576 0.1835 23.679);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.9128 0 0 / var(--ring-opacity)); /* #e2e2e2 hairline */
  --input: oklch(0.8669 0 0); /* #d3d3d3 — fields carry a touch more edge */
  --ring: oklch(0.5648 0.1585 275.564); /* #5e69d1 — Linear's focus indigo, a hair off the brand */
  --canvas: oklch(0.9524 0.0013 286.375); /* #efeff0 — the paper the sheet sits on */

  /* Surfaces are opaque: no glass anywhere. The modal scrim is the only dim. */
  --popover-opacity: 1;
  --backdrop-blur-popover: 0px;
  --overlay-opacity: 0.3;
  --backdrop-blur-overlay: 0px;
  --scroll-fade-size: 1.5rem;

  /* Elevation is EARNED here: controls and panels are held by hairlines, only floating surfaces lift.
     Hence a near-zero control tier, a 1x panel tier, and popover/modal tiers pushed way up. */
  --shadow-color: oklch(0.2217 0.0084 264.39);
  --shadow-highlight: oklch(1 0 0 / 0.08); /* matte: a whisper of top light, not a lit-paper rim */
  --shadow-size: 1;
  --shadow-opacity: 0.75;
  --shadow-control-multiplier: 0.6;
  --shadow-panel-multiplier: 1;
  --shadow-popover-multiplier: 5;
  --shadow-modal-multiplier: 8;

  /* A 1px focus hairline, not a 2px halo — Linear rings with the indigo, it does not glow. */
  --focus-ring-width: 1px;

  /* THE radius knob: 4px. Controls ride 2x (8px, Linear's --control-border-radius), panels 3x (12px).
     Never pill-shaped by token — the button pill is a deliberate slot choice, not a radius side effect. */
  --radius: 0.25rem;
  --radius-control: calc(var(--radius) * 2); /* 8px — buttons, rows, tabs, tree, sidebar */
  --radius-field: calc(var(--radius) * 2); /* 8px — composer shell, user bubble */
  --radius-panel: calc(var(--radius) * 3); /* 12px — dialogs, code, the content sheet */
  --radius-scene: calc(var(--radius) * 3.5); /* 14px */

  /* Linear insets each row 4px inside the menu and rounds it at 8px; the surface keeps the 12px panel corner. */
  --popover-padding: 0.25rem;
  --radius-popup-item: 0.5rem;
  --radius-popover: var(--radius-panel);

  --padding-x: 0.75rem;
  --padding-y: 0.5rem;

  /* Control ramp: 32px base, so `sm` lands on Linear's 28px chrome button. */
  --control-h: 2rem;

  /* Motion is a snap, not a glide — Linear's whole feel rests on this. 150ms is what its controls
     actually transition at; 250ms is its slowest (opacity) tempo. */
  --ease-standard: cubic-bezier(0.4, 0, 0.2, 1);
  --ease-emphasized: cubic-bezier(0.16, 1, 0.3, 1);
  --duration-fast: 150ms;
  --duration-base: 200ms;
  --duration-slow: 250ms;
}

/* Dark tokens: the real Linear night — near-black canvas, sheet one step up, menus three. */
:where(.dark) [data-skin="linear"][data-skin],
.dark[data-skin="linear"][data-skin] {
  --background: oklch(0.1826 0.002 286.198); /* #121213 */
  --foreground: oklch(1 0 0); /* Linear's primary ink is pure white, not off-white */
  --card: oklch(0.1826 0.002 286.198);
  --card-foreground: oklch(1 0 0);
  --popover: oklch(0.2482 0.0019 286.263); /* #212122 — menus sit well above the sheet */
  --popover-foreground: oklch(0.9247 0.0029 264.541); /* #e5e6e8 */
  --primary: oklch(0.5674 0.1585 275.206);
  --primary-foreground: oklch(1 0 0);
  --muted: oklch(0.2006 0.002 286.221); /* #161617 */
  --muted-foreground: oklch(0.6705 0.0029 286.321); /* #959597 */
  --secondary: oklch(0.2006 0.002 286.221);
  --secondary-foreground: oklch(0.9187 0.0029 264.541); /* #e3e4e6 */
  --accent: oklch(0.257 0.0037 286.136); /* #232325 */
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.576 0.1835 23.679);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.2517 0.004 264.495 / var(--ring-opacity)); /* #212224 */
  --input: oklch(0.278 0.0055 286.04); /* #28282b */
  --ring: oklch(0.6102 0.1404 276.317); /* the indigo lifts a rung to stay legible on ink */
  --canvas: oklch(0.1403 0.0022 286.109); /* #09090a */
  --shadow-color: oklch(0 0 0);
  --shadow-highlight: oklch(1 0 0 / 0.05);
  --shadow-opacity: 1;
}

/* prefers-reduced-motion: token-driven, so every derived tempo flattens together. */
@media (prefers-reduced-motion: reduce) {
  [data-skin="linear"][data-skin] {
    --duration-fast: 0ms;
    --duration-base: 0ms;
    --duration-slow: 0ms;
  }
}
